/** S01-REGMOV: un movimiento de MOVS264 ya explotado a una sola clave de transacción. */
public record MovimientoS264(
        int funcion, int sistema, int producto, int instrumento, int sucProm,
        String contrato,                 // 9(16): String para conservar ceros
        int cveTran,                     // 9(04): 1-999 S028, 1000-1999 S115
        BigDecimal importe,              // 9(14)V99 COMP -> escala 2
        LocalDate fecMov,                // 9(08) CCAAMMDD
        LocalTime horMov,                // S01-HORMOV-R: HORAMV, MINUMV, SEGMOV
        LocalDate fecCont, LocalDate fecVal,
        long autoriza, long aut3er,
        BigInteger refNum,               // 9(20): excede long, se usa BigInteger
        int cveMda, String numMda,       // 9(20) -> String
        int cveMde, int sucInic, int cajaInic, int sucOper, int cajaOper, int sucTran,
        int origen, String nominaOpe) {

    /** Llave de agrupación real del OUTPUT PROCEDURE (la CVETRAN solo ordena dentro del grupo). */
    public record Grupo(int moneda, int sucInic, BigInteger refNum) {}

    public Grupo grupo(int moneda) { return new Grupo(moneda, sucInic, refNum); }

    public Destino destino() {
        if (cveTran > 0 && cveTran < 1000) return Destino.S028;
        if (cveTran > 999 && cveTran < 2999) return Destino.S115;
        return Destino.NINGUNO;          // clave 0: posición vacía de la tabla de 5 claves
    }
}

